/**
 * @jest-environment node
 *
 * proxy.ts decides the language of a page before it renders: a ?lang= link, then the
 * device's saved choice, then the browser, then English. Only an explicit ?lang= is saved.
 *
 * Value: protects=the ?lang > cookie > Accept-Language > English order, the x-locale header
 * the root layout trusts, and saving only explicit choices; fails_when=the precedence is
 * reordered, a client-sent x-locale survives, or a guessed language is written to the cookie;
 * why_new=locale.test.ts covers negotiateLocale only, nothing ran proxy(); seam=none
 * Generated by /ship test coverage audit (pass 1).
 */
import type { NextRequest } from "next/server";
import { LOCALE_COOKIE, LOCALE_HEADER } from "@/lib/locale";

const mockCookieSet = jest.fn();
const mockNext = jest.fn((init: { request: { headers: Headers } }) => ({
  forwardedHeaders: init.request.headers,
  cookies: { set: mockCookieSet },
}));
jest.mock("next/server", () => ({ NextResponse: { next: (init: never) => mockNext(init) } }));

import { proxy } from "./proxy";

function pageRequest(url: string, { cookie, headers = {} }: { cookie?: string; headers?: Record<string, string> } = {}) {
  return {
    nextUrl: new URL(url),
    cookies: { get: (name: string) => (name === LOCALE_COOKIE && cookie !== undefined ? { name, value: cookie } : undefined) },
    headers: new Headers(headers),
  } as unknown as NextRequest;
}

function decided(request: NextRequest): string | null {
  const response = proxy(request) as unknown as { forwardedHeaders: Headers };
  return response.forwardedHeaders.get(LOCALE_HEADER);
}

beforeEach(() => {
  mockCookieSet.mockClear();
  mockNext.mockClear();
});

describe("proxy", () => {
  it("follows a ?lang= link over the saved choice and the browser, and saves it", () => {
    const request = pageRequest("http://app.test/register?lang=fr", {
      cookie: "en",
      headers: { "accept-language": "en-US" },
    });

    expect(decided(request)).toBe("fr");
    expect(mockCookieSet).toHaveBeenCalledWith(LOCALE_COOKIE, "fr", expect.objectContaining({ path: "/" }));
  });

  it("uses the saved choice over the browser, without rewriting it", () => {
    expect(decided(pageRequest("http://app.test/", { cookie: "fr", headers: { "accept-language": "en" } }))).toBe("fr");
    expect(mockCookieSet).not.toHaveBeenCalled();
  });

  it("falls back to the browser, then English, and never saves a guess", () => {
    expect(decided(pageRequest("http://app.test/", { headers: { "accept-language": "fr-CA,en;q=0.5" } }))).toBe("fr");
    expect(decided(pageRequest("http://app.test/"))).toBe("en");
    expect(mockCookieSet).not.toHaveBeenCalled();
  });

  it("ignores an unsupported ?lang= or cookie value", () => {
    expect(decided(pageRequest("http://app.test/?lang=es", { cookie: "de", headers: { "accept-language": "fr" } }))).toBe("fr");
    expect(mockCookieSet).not.toHaveBeenCalled();
  });

  it("overwrites an x-locale header sent by the client", () => {
    expect(decided(pageRequest("http://app.test/", { headers: { [LOCALE_HEADER]: "<script>", "accept-language": "en" } }))).toBe("en");
  });
});
